{"content": "{
  "user_need": "政治联姻，青梅竹马十年前边境战场重逢，压抑氛围，BE悲剧",
  "inspiration_state": "clear_inspiration",
  "extracted_elements": {
    "emotion_verbs": ["重逢", "压抑", "伪装", "爆发", "毁灭"],
    "scene_elements": ["军区大院新房", "岗哨监听", "结婚证", "军装伤疤", "战场手势暗语"],
    "relationship_tension": ["假装不认识 vs 旧情难忘", "组织安排 vs 个人情感", "十年生死两茫茫"],
    "user_preferences": {
      "desired_emotion": "BE、压抑到死的悲剧、彻底的毁灭",
      "forbidden": ["HE", "虚假的希望"]
    }
  },
  "selected_recipe": {
    "x_axis_mode_id": "G35",
    "x_axis_mode_name": "复得",
    "y_axis_tags": ["双向暗恋", "封闭空间"],
    "reaction_strength": "↘",
    "tension_stars": 5,
    "forbidden_elements": ["HE结局", "虚假希望", "任何一方主动告发对方"],
    "x_axis_display": "十年前边境战场，他以为她瞎了托付给牧民，她以为他死了。新婚夜重逢，却要装作不认识——承认旧情就是背叛组织安排的纯洁性。",
    "y_axis_combination_effect": "双向暗恋让假装不认识变成双向折磨；军区大院新房作为封闭空间强化压抑感；窗外岗哨、可能被监听的电话让每一次靠近都像偷情。",
    "reaction_formula": "十年生死两茫茫的重逢，应该是喜悦，却因为组织的政治任务变成人间炼狱。",
    "platform_fit": ["知乎盐选", "豆瓣阅读", "晋江文学城"]
  },
  "one_sentence_synopsis": "十年前以为死去的爱人成了组织安排的丈夫，新婚夜重逢却要假装不认识，承认旧情就是背叛。彻底的毁灭，无力的绝望。"
}
